# 04 T-RPT-02 ``report_code``, ``report_version`` → ``report_definition (code, version)``.
REPORT_DEFINITION_FK = (
    "ALTER TABLE erev.report_run ADD CONSTRAINT fk_report_run__report_definition "
    "FOREIGN KEY (report_code, report_version) REFERENCES erev.report_definition (code, version) "
    "ON DELETE RESTRICT ON UPDATE RESTRICT"
)
# Keys of earlier tables to the tables of this revision (DG-MIG-03), dropped first on downgrade.
INBOUND_KEYS: tuple[tuple[str, str, str], ...] = (
    ("lock_snapshot", "report_run_id", "report_run"),
    ("reconciliation", "report_run_id", "report_run"),
)


def _uuid(name: str, *, nullable: bool = True) -> sa.Column[Any]:
    return sa.Column(name, sa.Uuid(), nullable=nullable)


def _text(name: str, *, nullable: bool = True) -> sa.Column[Any]:
    return sa.Column(name, sa.Text(), nullable=nullable)


def _named(
    name: str, type_name: str, *, nullable: bool, default: str | None = None
) -> sa.Column[Any]:
    server_default = None if default is None else sa.text(default)
    return sa.Column(
        name, ops.NamedType(type_name), nullable=nullable, server_default=server_default
    )


def _uuid_array(name: str, *, default_empty: bool) -> sa.Column[Any]:
    server_default = sa.text("'{}'::uuid[]") if default_empty else None
    return sa.Column(name, ops.NamedType("uuid[]"), nullable=False, server_default=server_default)


def _instant(name: str, *, nullable: bool = True) -> sa.Column[Any]:
    return sa.Column(name, sa.DateTime(timezone=True), nullable=nullable)


def _date(name: str) -> sa.Column[Any]:
    return sa.Column(name, sa.Date(), nullable=True)


def _create_report_definition() -> None:
    table = "report_definition"
    ops.create_global_table(
        table,
        _text("code", nullable=False),
        sa.Column("version", sa.Integer(), nullable=False),
        _named("name", "erev.label", nullable=False),
        _text("kind", nullable=False),
        _named("description", "erev.memo", nullable=False),
        _named("parameters_schema", "jsonb", nullable=False),
        sa.Column("output_formats", sa.ARRAY(sa.Text()), nullable=False),
        _named("ipe_logic", "jsonb", nullable=False),
        sa.Column("tie_outs", sa.ARRAY(sa.Text()), nullable=False, server_default=sa.text("'{}'")),
        sa.Column("is_current", sa.Boolean(), nullable=False, server_default=sa.text("true")),
        primary_key=["code", "version"],
        checks=[
            ("ck_report_definition__kind", f"kind IN ({_literals(REPORT_KINDS)})"),
            ("ck_report_definition__version", "version >= 1"),
            (
                "ck_report_definition__output_formats",
                "cardinality(output_formats) >= 1 "
                f"AND output_formats <@ ARRAY[{_literals(OUTPUT_FORMATS)}]::text[]",
            ),
            (
                "ck_report_definition__tie_outs",
                f"tie_outs <@ ARRAY[{_literals(TIE_OUT_CODES)}]::text[]",
            ),
            (
                "ck_report_definition__parameters_schema",
                "jsonb_typeof(parameters_schema) = 'object'",
            ),
            ("ck_report_definition__ipe_logic", "jsonb_typeof(ipe_logic) = 'object'"),
        ],
        unique=[("ux_report_definition__current", ["code"], "is_current")],
    )
    ops.execute(REPORT_DEFINITION_SEED)
    ops.apply_class(table, "IM-A", global_reference=True)


def _create_report_run() -> None:
    table = "report_run"
    ops.create_tenant_table(
        table,
        _text("report_run_no", nullable=False),
        _text("report_code", nullable=False),
        sa.Column("report_version", sa.Integer(), nullable=False),
        _named("status", "erev.run_status", nullable=False, default="'QUEUED'"),
        _named("parameters", "jsonb", nullable=False),
        _uuid_array("entity_ids", default_empty=False),
        _named("book_code", "erev.book_code", nullable=True),
        _date("as_of_date"),
        _instant("known_at", nullable=False),
        _uuid("period_lock_id"),
        _uuid("engine_release_id", nullable=False),
        _text("output_format", nullable=False),
        _uuid("output_file_id"),
        _named("output_sha256", "erev.sha256", nullable=True),
        _uuid("manifest_file_id"),
        sa.Column("row_count", sa.BigInteger(), nullable=True),
        _named("control_totals", "jsonb", nullable=True),
        _named("tie_out_results", "jsonb", nullable=True),
        _named("ledger_heads", "jsonb", nullable=True),
        _uuid_array("child_report_run_ids", default_empty=True),
        _uuid_array("disclosure_snapshot_ids", default_empty=True),
        _uuid("job_id"),
        _instant("started_at"),
        _instant("finished_at"),
        _named("problem", "jsonb", nullable=True),
        standard_sets=["SC-C", "SC-M"],
        checks=[
            ("ck_report_run__output_format", f"output_format IN ({_literals(OUTPUT_FORMATS)})"),
            ("ck_report_run__row_count", "row_count IS NULL OR row_count >= 0"),
            ("ck_report_run__parameters", "jsonb_typeof(parameters) = 'object'"),
        ],
        unique=[("ux_report_run__no", ["tenant_id", "report_run_no"], None)],
        indexes=[("ix_report_run__code", ["tenant_id", "report_code", "created_at"], None)],
    )
    ops.execute(REPORT_DEFINITION_FK)
    ops.add_tenant_fk(table, "period_lock_id", "period_lock")
    ops.add_global_fk(table, "engine_release_id", "engine_release")
    ops.add_tenant_fk(table, "output_file_id", "file_object")
    ops.add_tenant_fk(table, "manifest_file_id", "file_object")
    ops.add_tenant_fk(table, "job_id", "job")
    ops.apply_class(table, "IM-S", update_columns=REPORT_RUN_UPDATE_COLUMNS)
    ops.enable_rls(table, "RLS-T")
    ops.create_trigger(
        table, "transition", REPORT_RUN_TRANSITION_BODY, timing="BEFORE", events="UPDATE"
    )


def _create_disclosure_snapshot() -> None:
    table = "disclosure_snapshot"
    ops.create_tenant_table(
        table,
        _named("disclosure_kind", "erev.disclosure_kind", nullable=False),
        _uuid("entity_id", nullable=False),
        _named("book_code", "erev.book_code", nullable=False),
        _uuid("period_id", nullable=False),
        _uuid("period_lock_id"),
        _uuid("report_run_id", nullable=False),
        _named("data", "jsonb", nullable=False),
        _named("data_sha256", "erev.sha256", nullable=False),
        standard_sets=["SC-C"],
        checks=[("ck_disclosure_snapshot__data", "jsonb_typeof(data) IN ('object', 'array')")],
        indexes=[
            (
                "ix_disclosure_snapshot__period",
                ["tenant_id", "entity_id", "book_code", "period_id", "disclosure_kind"],
                None,
            )
        ],
    )
    ops.add_tenant_fk(table, "entity_id", "legal_entity")
    ops.add_tenant_fk(table, "period_id", "period")
    ops.add_tenant_fk(table, "period_lock_id", "period_lock")
    ops.add_tenant_fk(table, "report_run_id", "report_run")
    ops.apply_class(table, "IM-A")
    ops.enable_rls(table, "RLS-TE", entity_column="entity_id")


def _create_evidence_pack() -> None:
    table = "evidence_pack"
    ops.create_tenant_table(
        table,
        _text("pack_no", nullable=False),
        _named("kind", "erev.evidence_pack_kind", nullable=False),
        _uuid("entity_id"),
        _named("book_code", "erev.book_code", nullable=True),
        _uuid("period_id"),
        _uuid("period_lock_id"),
        _uuid_array("contract_ids", default_empty=True),
        _date("as_of_date"),
        _date("from_date"),
        _date("to_date"),
        _named("status", "erev.run_status", nullable=False, default="'QUEUED'"),
        _named("manifest", "jsonb", nullable=True),
        _named("manifest_sha256", "erev.sha256", nullable=True),
        _uuid("file_id"),
        _uuid_array("report_run_ids", default_empty=True),
        _uuid("job_id"),
        standard_sets=["SC-C", "SC-M"],
        checks=[
            (
                "ck_evidence_pack__close",
                "kind <> 'CLOSE' OR (entity_id IS NOT NULL AND book_code IS NOT NULL "
                "AND period_id IS NOT NULL AND period_lock_id IS NOT NULL)",
            ),
            (
                "ck_evidence_pack__sample",
                "kind <> 'CONTRACT_SAMPLE' OR (cardinality(contract_ids) >= 1 "
                "AND as_of_date IS NOT NULL)",
            ),
            (
                "ck_evidence_pack__change",
                "kind <> 'CHANGE' OR (from_date IS NOT NULL AND to_date IS NOT NULL)",
            ),
            ("ck_evidence_pack__access", "kind <> 'ACCESS' OR as_of_date IS NOT NULL"),
            (
                "ck_evidence_pack__date_range",
                "to_date IS NULL OR from_date IS NULL OR to_date >= from_date",
            ),
        ],
        unique=[("ux_evidence_pack__no", ["tenant_id", "pack_no"], None)],
    )
    ops.add_tenant_fk(table, "entity_id", "legal_entity")
    ops.add_tenant_fk(table, "period_id", "period")
    ops.add_tenant_fk(table, "period_lock_id", "period_lock")
    ops.add_tenant_fk(table, "file_id", "file_object")
    ops.add_tenant_fk(table, "job_id", "job")
    ops.apply_class(table, "IM-S", update_columns=EVIDENCE_PACK_UPDATE_COLUMNS)
    ops.enable_rls(table, "RLS-T")
    ops.create_trigger(
        table, "transition", EVIDENCE_PACK_TRANSITION_BODY, timing="BEFORE", events="UPDATE"
    )


def upgrade() -> None:
    """Create the item's objects through the §6.5 helpers, in 04 §18 dependency order."""
    for name, values in ENUMS:
        ops.create_enum(name, values)
    _create_report_definition()
    _create_report_run()
    _create_disclosure_snapshot()
    _create_evidence_pack()
    for table, column, target in INBOUND_KEYS:
        ops.add_tenant_fk(table, column, target)


def downgrade() -> None:
    """Remove exactly what upgrade() created, in reverse order (DG-MIG-04)."""
    for table, _column, target in reversed(INBOUND_KEYS):
        ops.execute(f"ALTER TABLE erev.{table} DROP CONSTRAINT fk_{table}__{target}")
    for table in ("evidence_pack", "disclosure_snapshot", "report_run"):
        ops.drop_tenant_table(table)
    ops.drop_global_table("report_definition")
    for name, _ in reversed(ENUMS):
        ops.drop_enum(name)
